set-variable.value:
@{
    var header = context.Request.Headers.GetValueOrDefault("Authorization", "");
    var jwt = header.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase) ? header.Substring(7).AsJwt() : null;
    return jwt == null ? "none" : jwt.Claims.GetValueOrDefault("oid", "none");
  }

@{
    var header = context.Request.Headers.GetValueOrDefault("Authorization", "");
    var jwt = header.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase) ? header.Substring(7).AsJwt() : null;
    return jwt == null ? "none" : jwt.Claims.GetValueOrDefault("azp", jwt.Claims.GetValueOrDefault("appid", "none"));
  }
